int kh1_cn_steam_Apply(HMODULE module)
{
    unsigned char *base = (unsigned char *)module;
    size_t count = sizeof(g_patches) / sizeof(g_patches[0]);
    size_t applied = 0;
    for (size_t i = 0; i < count; i++) {
        PatchEntry *p = &g_patches[i];
        unsigned char *addr = base + p->rva;
        if (memcmp(addr, p->orig, p->len) != 0) {
            if (memcmp(addr, p->patch, p->len) == 0) {
                applied++;
                continue;
            }
            char msg[256];
            snprintf(msg, sizeof(msg),
                "[kh1_cn_steam] Patch %zu verification failed at RVA 0x%llX (%s)",
                i, (unsigned long long)p->rva, p->sect);
            OutputDebugStringA(msg);
            continue;
        }
        DWORD oldProtect;
        if (!VirtualProtect(addr, p->len, PAGE_EXECUTE_READWRITE, &oldProtect)) {
            char msg[256];
            snprintf(msg, sizeof(msg),
                "[kh1_cn_steam] VirtualProtect failed for patch %zu at RVA 0x%llX err=%lu",
                i, (unsigned long long)p->rva, GetLastError());
            OutputDebugStringA(msg);
            continue;
        }
        memcpy(addr, p->patch, p->len);
        DWORD dummy;
        VirtualProtect(addr, p->len, oldProtect, &dummy);
        applied++;
    }
    return (applied == count) ? 1 : 0;
}
